# Explore & Reflect worksheets for the Statistics audit labs (#15). Same structure as the Calculus audit labs:
# predict, explore, record, rules, explain, apply, teacher. Every number is recomputed by tests/worksheet-answers.py.
W = {}

W['statistics-normal-curve-lab'] = dict(
  predict=[("IQ scores are N(100, 15). Do you think more or less than 5% of people have an IQ above 130? Why?", "Less: 130 is 2 SDs above the mean, and only about 2.5% of a Normal distribution is beyond +2 SD.", 1),
           ("Two Normal models have different means and SDs. Is the area to the left of z = 1 the same for both?", "Yes. Every Normal curve has the same area to the left of the same z-score (about 0.8413).", 1)],
  explore=[("IQ N(100, 15): shade X > 130. Record z and the shaded area.", "z = 2; area ≈ 0.0228", 1),
           ("Heights N(64, 2.5): shade X < 60. Record z and the area.", "z = −1.6; area ≈ 0.0548", 1),
           ("Scores N(500, 100): shade 400 < X < 650. Record both z-scores and the area.", "z = −1 and 1.5; area ≈ 0.7745", 1),
           ("Use the inverse mode to find the 90th percentile of IQ scores. Record z and a.", "z ≈ 1.28; a ≈ 119.22", 1)],
  record=[dict(title="Normal areas", note="Round areas to 4 decimal places.",
     head=["Model", "Region", "z-score(s)", "Area (exact)", "Area (Table A)"],
     rows=[["N(100, 15)", "X > 130", "?2", "?0.0228", "?0.0228"], ["N(64, 2.5)", "X < 60", "?−1.6", "?0.0548", "?0.0548"],
           ["N(500, 100)", "400 < X < 650", "?−1 and 1.5", "?0.7745", "?0.7745"], ["N(0, 1)", "both tails beyond ±1.96", "?±1.96", "?0.05", "?0.05"]])],
  rules=[("To standardize a value x, compute z = ___.", ["(x − μ)/σ"]),
         ("Table A gives the area to the ___ of z.", ["left"]),
         ("The area to the right of z is 1 minus ___.", ["the Table A area"]),
         ("For a percentile, find z in the table, then a = ___.", ["μ + zσ"])],
  explain=("Explain why P(X > 130) for IQ N(100, 15) is the same as P(X > 69) for heights N(64, 2.5).",
           "Both cutoffs are 2 standard deviations above their means (z = 2), and every Normal curve has the same area beyond the same z-score.", 3),
  apply=[("Apple weights are N(150, 20) grams. What proportion weigh more than 180 g?", "z = 1.5; 1 − 0.9332 = 0.0668"),
         ("What weight marks the 25th percentile of apple weights?", "z ≈ −0.67; 150 − 0.67(20) ≈ 136.6 g"),
         ("What proportion of apples weigh between 140 g and 170 g?", "z = −0.5 and 1; 0.8413 − 0.3085 = 0.5328"),
         ("A student scores 650 on a test that is N(500, 100) and 31 on a test that is N(24, 4). On which test did the student do relatively better?", "z = 1.5 and 1.75: relatively better on the second test")],
  teacher=dict(discovery="Areas under a Normal curve depend only on z = (x − μ)/σ; Table A gives left-tail areas, other regions come from subtraction, and percentiles come from reading the table backward and un-standardizing.",
    misconceptions=["Using the Table A area for a right tail without subtracting from 1.", "Forgetting to un-standardize after finding z for a percentile.",
                    "Thinking a larger σ changes the area to the left of the same z-score."],
    varies="Table A answers can differ from the exact areas in the fourth decimal place; both are acceptable."))

W['statistics-chi-square-lab'] = dict(
  predict=[("A claim says four colors are equally likely. In 100 candies you see 30, 22, 28 and 20. Do you think this is convincing evidence against the claim?", "No: the counts are close to 25 each; chance alone could easily give differences this large.", 1),
           ("If every count were doubled (60, 44, 56, 40), would the evidence be stronger, weaker or the same?", "Stronger: the same proportions with a larger sample give a larger χ² and a smaller p-value.", 1)],
  explore=[("Equal claim, counts 30, 22, 28, 20. Record the expected counts, χ² and the p-value.", "E = 25 each; χ² = 2.72; p ≈ 0.4368", 1),
           ("Same counts against the claim 40%, 30%, 20%, 10%. Record χ² and the p-value.", "χ² ≈ 17.833; p ≈ 0.0005", 1),
           ("Double the counts (60, 44, 56, 40) with the equal claim. Record χ² and the p-value.", "χ² = 5.44; p ≈ 0.1423", 1),
           ("Independence mode: use the starting table (juniors 30, 25, 15; seniors 20, 25, 35). Record χ², df and the p-value.", "χ² = 9.375; df = 2; p ≈ 0.0092", 1)],
  record=[dict(title="Chi-square results", note="Round χ² to 3 decimal places and p-values to 4.",
     head=["Test", "Claim or table", "Observed", "χ²", "df", "p-value"],
     rows=[["Goodness of fit", "25% each", "30, 22, 28, 20", "?2.72", "?3", "?0.4368"], ["Goodness of fit", "30%, 20%, 20%, 30%", "30, 22, 28, 20", "?6.733", "?3", "?0.0809"],
           ["Goodness of fit", "40%, 30%, 20%, 10%", "30, 22, 28, 20", "?17.833", "?3", "?0.0005"], ["Independence", "2 × 3 table", "30, 25, 15 / 20, 25, 35", "?9.375", "?2", "?0.0092"]])],
  rules=[("For goodness of fit, the expected count is E = ___.", ["n × (claimed proportion)"]),
         ("For a two-way table, E = ___.", ["(row total × column total)/table total"]),
         ("The chi-square statistic is χ² = ___.", ["Σ (O − E)²/E"]),
         ("Degrees of freedom: categories − 1 for goodness of fit, and ___ for a two-way table.", ["(rows − 1)(columns − 1)"])],
  explain=("Explain why doubling every count, without changing the proportions, makes the evidence against the claim stronger.",
           "Each (O − E)²/E doubles (both O − E and E double), so χ² doubles while df stays the same; a larger χ² has a smaller p-value. Bigger samples make the same proportional difference less likely to be chance.", 3),
  apply=[("A die is rolled 120 times. What is the expected count for each face if the die is fair?", "120 × 1/6 = 20"),
         ("For one face, O = 28 and E = 20. What is that face's piece of χ²?", "(28 − 20)²/20 = 3.2"),
         ("A 3 × 4 table is tested for independence. How many degrees of freedom does the test use?", "(3 − 1)(4 − 1) = 6"),
         ("A goodness-of-fit test with 4 categories gives χ² = 7.815. Is the result significant at α = 0.05?", "The critical value for df = 3 is about 7.815, so the p-value is about 0.05: right at the cutoff.")],
  teacher=dict(discovery="χ² = Σ(O − E)²/E measures how far the counts are from what the claim or independence predicts; a large χ² gives a small p-value, and with the same proportions a larger sample gives a larger χ².",
    misconceptions=["Using proportions instead of counts in (O − E)²/E.", "Using df = n − 1 instead of categories − 1.",
                    "Ignoring the expected-count condition (all E ≥ 5)."],
    varies="Students may report p-values from the lab with more decimal places; the decision at α = 0.05 is what matters."))
